import java.util.*;

public class Main {
    static final int Mod = 1000000007;

    static int power(int b, int e) {
        if (e == 0) return 1;
        int tmp = power(b, e >> 1);
        tmp = (int) ((long) tmp * tmp % Mod);
        if ((e & 1) == 1) tmp = (int) ((long) tmp * b % Mod);
        return tmp;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[][] p = new int[10][10];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int per = sc.nextInt();
                p[i][j] = (int) ((long) per * power(100, Mod - 2) % Mod);
            }
        }
        for (int i = n; i <= 5; i++) {
            p[i][i] = 1;
        }

        List<Integer> com = new ArrayList<>();
        for (int i = 0; i < (1 << 6); i++) {
            int cnt = 0;
            for (int j = 0; j <= 5; j++) {
                if ((i & (1 << j)) != 0) cnt++;
            }
            if (cnt == 3) {
                com.add(i);
            }
        }

        int sizeF = 1 << 20;
        int[] f = new int[sizeF];
        int[] g = new int[sizeF];

        for (int i = 0; i < (1 << 6); i++) {
            for (int j = 0; j < (1 << 6); j++) {
                boolean[][] b = new boolean[6][6];
                int tmp = 0;
                int mask = 0;
                int pos = 1;
                for (int jIdx = 0; jIdx <= 5; jIdx++) {
                    for (int k = 0; k <= 2; k++) {
                        if ((i & (1 << jIdx)) != 0 && (j & (1 << jIdx)) != 0) {
                            b[jIdx][k] = true;
                            pos = (int) ((long) pos * p[jIdx][k] % Mod);
                        } else {
                            pos = (int) ((long) pos * (Mod + 1 - p[jIdx][k]) % Mod);
                        }
                        tmp++;
                    }
                }
                for (int jIdx = 0; jIdx < 20; jIdx++) {
                    int[] pArr = new int[3];
                    int pCount = 0;
                    int s = com.get(jIdx) ^ 63;
                    for (int k = 0; k <= 5; k++) {
                        if ((s & (1 << k)) != 0) {
                            pArr[pCount++] = k;
                        }
                    }
                    int p1 = pArr[0], p2 = pArr[1], p3 = pArr[2];
                    if ((b[p1][0] && b[p2][1] && b[p3][2]) ||
                        (b[p1][0] && b[p2][2] && b[p3][1]) ||
                        (b[p1][1] && b[p2][0] && b[p3][2]) ||
                        (b[p1][1] && b[p2][2] && b[p3][0]) ||
                        (b[p1][2] && b[p2][0] && b[p3][1]) ||
                        (b[p1][2] && b[p2][1] && b[p3][0])) {
                        mask |= 1 << jIdx;
                    }
                }
                f[mask] = (f[mask] + pos) % Mod;
            }
        }

        for (int i = 0; i < (1 << 6); i++) {
            for (int j = 0; j < (1 << 6); j++) {
                boolean[][] b = new boolean[6][6];
                int tmp = 0;
                int mask = 0;
                int pos = 1;
                for (int jIdx = 0; jIdx <= 5; jIdx++) {
                    for (int k = 3; k <= 5; k++) {
                        if ((i & (1 << jIdx)) != 0 && (j & (1 << jIdx)) != 0) {
                            b[jIdx][k] = true;
                            pos = (int) ((long) pos * p[jIdx][k] % Mod);
                        } else {
                            pos = (int) ((long) pos * (Mod + 1 - p[jIdx][k]) % Mod);
                        }
                        tmp++;
                    }
                }
                for (int jIdx = 0; jIdx < 20; jIdx++) {
                    int[] pArr = new int[3];
                    int pCount = 0;
                    int s = com.get(jIdx) ^ 63;
                    for (int k = 0; k <= 5; k++) {
                        if ((s & (1 << k)) != 0) {
                            pArr[pCount++] = k;
                        }
                    }
                    int p1 = pArr[0], p2 = pArr[1], p3 = pArr[2];
                    if ((b[p1][3] && b[p2][4] && b[p3][5]) ||
                        (b[p1][3] && b[p2][5] && b[p3][4]) ||
                        (b[p1][4] && b[p2][3] && b[p3][5]) ||
                        (b[p1][4] && b[p2][5] && b[p3][3]) ||
                        (b[p1][5] && b[p2][3] && b[p3][4]) ||
                        (b[p1][5] && b[p2][4] && b[p3][3])) {
                        mask |= 1 << jIdx;
                    }
                }
                g[mask] = (g[mask] + pos) % Mod;
            }
        }

        for (int i = 0; i < 20; i++) {
            for (int j = (1 << 20) - 1; j >= 0; j--) {
                if ((j & (1 << i)) != 0) {
                    g[j] = (g[j] + g[j ^ (1 << i)]) % Mod;
